    const flap = o.wings === false ? 0 : Math.sin(tw(t) * 40 + seed) * 0.35;
    const wasp = !!o.wasp, fur = !!o.fur;
    // back wing
    c.save(); c.translate(0, -34); c.rotate(-0.5 - flap); sh(c, el(-30, -40, 30, 56, 30), 'rgba(251,246,234,0.75)', 3, seed + 1, { grain: 0 }); c.restore();
    // stinger
