    const stripes = (wasp ? [-96, -66, -36] : [-92, -60, -28]).map((sx) => ({ pts: [[sx, -80], [sx + 16, -80], [sx + 12, 80], [sx - 4, 80]], color: C.ink }));
    if (fur) stripes.push({ pts: [[-140, -80], [-104, -80], [-108, 80], [-140, 80]], color: C.white });
    sh(c, ab, C2.beeY, 3.5, seed + 4, { shade: stripes.concat([{ pts: el(-50, 34, 80, 26, 20), color: C2.beeD, alpha: 0.6 }]) });
    if (wasp) sh(c, el(-2, 0, 14, 10, 16), C.ink, 0, seed + 5, { grain: 0 });
    // thorax
    sh(c, el(26, -4, fur ? 40 : 36, fur ? 38 : 33, 30), fur ? C2.beeY : C.kraftD, 3.5, seed + 6, { shade: [{ pts: el(30, 18, 40, 16, 16), color: C.brown, alpha: 0.6 }] });
