    const bands = [[-150, 0, 300], [-140, -48, 280], [-118, -96, 236], [-88, -140, 176], [-50, -176, 100]];
    bands.forEach(([bx, by, bw], i) => sh(c, rr(bx, by - 52, bw, 56, 26), i % 2 ? C.kraftL : C.kraft, 3.5, 920 + i, { shade: [{ pts: [[bx + bw * 0.6, by - 60], [bx + bw + 10, by - 60], [bx + bw + 10, by + 10], [bx + bw * 0.6, by + 10]], color: C.kraftD, alpha: 0.5 }] }));
