    k.play('ding', P(53, 'target'), { f: 'A5', gain: 0.25 });
    k.play('sparkle', P(55, 'worker'), { n: 5, gain: 0.3 }); vib(P(56, 'protected'), ['C5', 'E5', 'G5', 'B5'], 0.9);
