    k.play('erase', P(58, 'scraping'), { dur: 0.4, gain: 0.35 }); k.play('pop', P(58, 'pinching') + 0.3, { f: 700, gain: 0.35 }); k.play('ding', P(58, 'same'), { f: 'G5', gain: 0.25 });
    k.play('click', P(59, 'speed'), { f: 1800, gain: 0.6 }); k.play('stamp', P(59, 'speed'), { gain: 0.45 });
    for (let x = P(59, 'speed'); x < PE(60); x += 0.5) k.play('tick', x, { f: 5200, gain: 0.25 }); pump(P(60, 'every'), PE(60), 3, 0.8);
    k.play('sparkle', P(61, 'stomach'), { n: 6, gain: 0.35 }); for (let i = 0; i < 6; i++) k.play('blip', P(61, 'acid') + i * 0.18, { f: 'C6', type: 'sine', gain: 0.15, minor: true });
    vib(PE(62) + 0.2, ['D4', 'F4', 'A4', 'C5'], 1);
